import json
R,C=29,23
g=[[1]*C for _ in range(R)]
# color-3 pattern, coordinates are zero-indexed as in displayed grid
for c in list(range(10,19))+[20,21]: g[13][c]=3
for r in range(14,23):
    g[r][10]=3; g[r][21]=3
for r in [14,16,17]: g[r][13]=3
for c in range(10,22): g[23][c]=3
# Fill background gaps between pairs of same-color cells aligned horizontally/vertically.
out=[row[:] for row in g]
for r in range(R):
    cols=[c for c,v in enumerate(g[r]) if v==3]
    for a,b in zip(cols,cols[1:]):
        if b>a+1:
            for c in range(a+1,b): out[r][c]=2
for c in range(C):
    rows=[r for r in range(R) if g[r][c]==3]
    for a,b in zip(rows,rows[1:]):
        if b>a+1:
            for r in range(a+1,b): out[r][c]=2
assert len(out)==29 and all(len(row)==23 for row in out)
print(json.dumps(out,separators=(',',':')))

# Re-derive candidate: connect consecutive occurrences of the signal color along each row/column,
# without crossing through any other color cells; preserve original signal cells.
