for c in list(range(10,19))+[20,21]: src[13][c]=3
for r in range(14,23): src[r][10]=src[r][21]=3
for r in (14,16,17): src[r][13]=3
for c in range(10,22):src[23][c]=3
out=[row[:] for row in src]
for r in range(R):
    ps=[c for c in range(C) if src[r][c]==3]
    for a,b in zip(ps,ps[1:]):
        for c in range(a+1,b):
            if src[r][c]==1: out[r][c]=2
for c in range(C):
    ps=[r for r in range(R) if src[r][c]==3]
    for a,b in zip(ps,ps[1:]):
        for r in range(a+1,b):
            if src[r][c]==1: out[r][c]=2
print('shape',len(out),set(map(len,out)),'changes',[(r,c,out[r][c]) for r in range(R) for c in range(C) if src[r][c]!=out[r][c]])

